// src/components/Navbar.js
import React, { useState } from 'react';
import { Link } from 'react-router-dom';
import './Navbar.css';

const Navbar = () => {
    const [isOpen, setIsOpen] = useState(false);

    return (
        <header className="main-header">
            <div className="logo-wrapper">
                <Link to="/">
                    <img src="/assets/lbslmain.png" className="logo" alt="Infinity Logo" />
                </Link>
            </div>
            
            <nav id="mainNav" className={isOpen ? 'active' : ''}>
                <ul>
                    <li><Link to="/">Home</Link></li>
                    <li><Link to="/about">About Us</Link></li>
                    <li><Link to="/services">Services</Link></li>
                    <li><Link to="/branches">Branches</Link></li>
                    <li><Link to="/investor-relations">Investor Relations</Link></li>
                    <li><Link to="/media">Media</Link></li>
                    <li><Link to="/contact">Contact</Link></li>
                    <li><Link to="/loan" className="btn-loan">Loan Apply</Link></li>
                    <li><a href="mailto:info@infinitylbsl.com.np" className="btn-mail">Mail</a></li>
                </ul>
            </nav>

            <div className="menu-toggle" onClick={() => setIsOpen(!isOpen)}>
                {isOpen ? '✕' : '☰'}
            </div>
        </header>
    );
};

export default Navbar;
